import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { VitePWA } from 'vite-plugin-pwa'

export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: 'autoUpdate',
      includeAssets: ['favicon.svg', 'apple-touch-icon.png'],
      manifest: {
        name: 'Rhythm — Habit & Stimmungs-Tracker',
        short_name: 'Rhythm',
        description:
          'Ein offlinefahiger Habit- und Stimmungs-Tracker. Verfolge deine Routinen und deine Laune.',
        theme_color: '#1a1a1a',
        icons: [
          {
            src: 'pwa-192x192.png',
            sizes: '192x192',
            type: 'image/png',
          },
          {
            src: 'pwa-512x512.png',
            sizes: '512x512',
            type: 'image/png',
          },
          {
            src: 'pwa-512x512.png',
            sizes: '512x512',
            type: 'image/png',
            purpose: 'any maskable',
          },
        ],
      },
    }),
  ],
})

import { openDB } from 'idb'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

export interface Habit {
  id: string
  name: string
  emoji: string
  color: string
  createdAt: number
}

export interface CheckIn {
  habitId: string
  date: string // YYYY-MM-DD
}

export interface MoodEntry {
  date: string // YYYY-MM-DD
  value: number // 1-5
  note?: string
}

let db: IDBPDatabase | null = null

async function getDb(): Promise<IDBPDatabase> {
  if (!db) {
    db = await openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        db.createObjectStore('habits', { keyPath: 'id' })
        db.createObjectStore('checkins', { keyPath: ['habitId', 'date'] })
        db.createObjectStore('moods', { keyPath: 'date' })
      },
    })
  }
  return db
}

// ── Habits ──

export async function getHabits(): Promise<Habit[]> {
  return (await getDb()).getAll('habits')
}

export async function addHabit(name: string, emoji: string, color: string): Promise<string> {
  const id = crypto.randomUUID()
  const habit: Habit = { id, name, emoji, color, createdAt: Date.now() }
  await (await getDb()).put('habits', habit)
  return id
}

export async function updateHabit(id: string, updates: Partial<Pick<Habit, 'name' | 'emoji' | 'color'>>): Promise<void> {
  const db = await getDb()
  const habit = await db.get('habits', id)
  if (habit) {
    Object.assign(habit, updates)
    await db.put('habits', habit)
  }
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDb()
  await db.delete('habits', id)
}

// ── Check-ins ──

export async function getCheckinsForDate(date: string): Promise<string[]> {
  const habits = await getHabits()
  const db = await getDb()
  const completed: string[] = []
  for (const habit of habits) {
    const checkin = await db.getFromStore('checkins', [habit.id, date])
    if (checkin) completed.push(habit.id)
  }
  return completed
}

export async function toggleCheckIn(habitId: string, date: string): Promise<void> {
  const db = await getDb()
  const existing = await db.get('checkins', [habitId, date])
  if (existing) {
    await db.delete('checkins', [habitId, date])
  } else {
    await db.put('checkins', { habitId, date })
  }
}

export async function getCheckinsForDateRange(startDate: string, endDate: string): Promise<Map<string, string[]>> {
  const habits = await getHabits()
  const db = await getDb()
  const result = new Map<string, string[]>()
  let current = new Date(startDate)
  while (current <= new Date(endDate)) {
    const date = current.toISOString().slice(0, 10)
    result.set(date, [])
    for (const habit of habits) {
      const checkin = await db.getFromStore('checkins', [habit.id, date])
      if (checkin) {
        result.get(date)!.push(habit.id)
      }
    }
    current.setDate(current.getDate() + 1)
  }
  return result
}

// ── Streak calculation ──

export function calculateStreaks(habits: Habit[]): { current: number; longest: number }[] {
  return habits.map((habit) => {
    const today = new Date()
    today.setHours(0, 0, 0, 0)

    // Get all checkins for this habit
    const dates: Date[] = []
    // We need to check backwards from today
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    // Current streak
    let currentStreak = 0
    let checkDate = new Date(today)
    while (true) {
      const dateStr = checkDate.toISOString().slice(0, 10)
      const exists = (async () => {
        const db = await getDb()
        return await db.get('checkins', [habit.id, dateStr])
      })()
      // We can't use async in sync function, so we'll handle this differently
      // For now, return a basic calculation
      break
    }

    return { current: 0, longest: 0 }
  })
}

// ── Moods ──

export async function saveMood(entry: Omit<MoodEntry, 'date'> & { date: string }): Promise<void> {
  await (await getDb()).put('moods', { ...entry, date: entry.date })
}

export async function getMoodForDate(date: string): Promise<MoodEntry | null> {
  return (await getDb()).get('moods', date)
}

export async function getMoodsForDateRange(startDate: string, endDate: string): Promise<MoodEntry[]> {
  const db = await getDb()
  const allMoods = await db.getAll('moods')
  return allMoods.filter((m) => m.date >= startDate && m.date <= endDate)
}

export async function getTodayString(): Promise<string> {
  return new Date().toISOString().slice(0, 10)
}

// ── Theme ──

const THEME_KEY = 'rhythm-theme'

export function getStoredTheme(): 'light' | 'dark' | null {
  try {
    const stored = localStorage.getItem(THEME_KEY)
    return stored === 'light' || stored === 'dark' ? stored : null
  } catch {
    return null
  }
}

export function setStoredTheme(theme: 'light' | 'dark'): void {
  try {
    localStorage.setItem(THEME_KEY, theme)
  } catch {
    // ignore
  }
}

export function prefersDark(): boolean {
  try {
    return window.matchMedia('(prefers-color-scheme: dark)').matches
  } catch {
    return false
  }
}

export function useSystemTheme(): boolean {
  try {
    return !!window.matchMedia('(prefers-color-scheme: dark)').matches
  } catch {
    return false
  }
}

import { openDB, IDBPDatabase } from 'idb'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

// ── Types ──

export interface Habit {
  id: string
  name: string
  emoji: string
  color: string
  createdAt: number
}

export interface CheckIn {
  habitId: string
  date: string // YYYY-MM-DD
}

export interface MoodEntry {
  date: string // YYYY-MM-DD
  value: number // 1-5
  note?: string
}

// ── DB singleton ──

let _db: IDBPDatabase | null = null

async function open(): Promise<IDBPDatabase> {
  if (!_db) {
    _db = await openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        db.createObjectStore('habits', { keyPath: 'id' })
        const cs = db.createObjectStore('checkins', { keyPath: ['habitId', 'date'] })
        cs.createIndex('byHabit', 'habitId')
        db.createObjectStore('moods', { keyPath: 'date' })
      },
    })
  }
  return _db
}

// ── Habits ──

export async function getHabits(): Promise<Habit[]> {
  return (await open()).getAll('habits')
}

export async function addHabit(name: string, emoji: string, color: string): Promise<string> {
  const id = crypto.randomUUID()
  await (await open()).put('habits', { id, name, emoji, color, createdAt: Date.now() })
  return id
}

export async function updateHabit(id: string, partial: Partial<Pick<Habit, 'name' | 'emoji' | 'color'>>): Promise<void> {
  const db = await open()
  const h = await db.get('habits', id)
  if (h) Object.assign(h, partial), await db.put('habits', h)
}

export async function removeHabit(id: string): Promise<void> {
  await (await open()).delete('habits', id)
}

// ── Check-ins ──

export async function getCheckinsToday(): Promise<Set<string>> {
  const habits = await getHabits()
  const today = getTodayString()
  const set = new Set<string>()
  for (const habit of habits) {
    const c = await (await open()).get('checkins', [habit.id, today])
    if (c) set.add(habit.id)
  }
  return set
}

export async function toggleCheckIn(habitId: string): Promise<void> {
  const db = await open()
  const today = getTodayString()
  const exists = await db.get('checkins', [habitId, today])
  if (exists) await db.delete('checkins', [habitId, today])
  else await db.put('checkins', { habitId, date: today })
}

export interface DailyCounts {
  date: string
  completed: string[]
  mood?: MoodEntry
}

export async function getWeeklyData(): Promise<DailyCounts[]> {
  const habits = await getHabits()
  const db = await open()
  const data: DailyCounts[] = []
  const today = new Date()

  for (let i = 6; i >= 0; i--) {
    const d = new Date(today)
    d.setDate(d.getDate() - i)
    const dateStr = d.toISOString().slice(0, 10)

    const completed: string[] = []
    for (const habit of habits) {
      const c = await db.get('checkins', [habit.id, dateStr])
      if (c) completed.push(habit.id)
    }

    const mood = await db.get('moods', dateStr)

    data.push({ date: dateStr, completed, mood })
  }

  return data
}

// ── Streaks (async-friendly) ──

export interface Streaks {
  current: number
  longest: number
}

export async function getStreaks(): Promise<Record<string, Streaks>> {
  const habits = await getHabits()
  const db = await open()
  const result: Record<string, Streaks> = {}

  for (const habit of habits) {
    // Current streak
    let current = 0
    let d = new Date()
    d.setHours(0, 0, 0, 0)

    while (true) {
      const dateStr = d.toISOString().slice(0, 10)
      const c = await db.get('checkins', [habit.id, dateStr])
      if (c) {
        current++
        d.setDate(d.getDate() - 1)
      } else {
        break
      }
    }

    // Longest streak: scan all months (last 365 days)
    let longest = 0
    let running = 0
    for (let offset = 365; offset >= 0; offset--) {
      const check = new Date()
      check.setDate(check.getDate() - offset)
      check.setHours(0, 0, 0, 0)
      const dateStr = check.toISOString().slice(0, 10)
      const c = await db.get('checkins', [habit.id, dateStr])
      if (c) {
        running++
        longest = Math.max(longest, running)
      } else {
        running = 0
      }
    }

    result[habit.id] = { current, longest }
  }

  return result
}

// ── Moods ──

export async function saveMood(value: number, note?: string): Promise<void> {
  const today = getTodayString()
  await (await open()).put('moods', { date: today, value, note })
}

export async function getTodayMood(): Promise<MoodEntry | null> {
  return (await open()).get('moods', getTodayString())
}

// ── Helpers ──

export function getTodayString(): string {
  return new Date().toISOString().slice(0, 10)
}

export function formatDateGerman(dateStr: string): string {
  const months = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez']
  const [y, m, d] = dateStr.split('-')
  return `${parseInt(d, 10)}. ${months[parseInt(m, 10) - 1]} ${y}`
}

// ── Theme storage ──

const THEME_KEY = 'rhythm-theme-mode'

export function readTheme(): 'light' | 'dark' | null {
  try {
    const v = localStorage.getItem(THEME_KEY)
    return v === 'light' || v === 'dark' ? v : null
  } catch {
    return null
  }
}

export function writeTheme(mode: 'light' | 'dark'): void {
  try {
    localStorage.setItem(THEME_KEY, mode)
  } catch {
    /* offline storage may reject — that's fine */
  }
}

export function systemDark(): boolean {
  try {
    return !!matchMedia('(prefers-color-scheme: dark)').matches
  } catch {
    return false
  }
}

@import 'tailwindcss';

@theme {
  --color-bg: #faf9f7;
  --color-surface: #ffffff;
  --color-surface-pressed: #f0efed;
  --color-text: #1a1a1a;
  --color-text-secondary: #777774;
  --color-text-tertiary: #a09f9c;
  --color-border: rgba(0, 0, 0, 0.06);
  --color-accent: #1a1a1a;
  --color-accent-text: #ffffff;
  --color-habit-1: #c4956a;
  --color-habit-2: #6a9c8a;
  --color-habit-3: #8a7ab0;
  --color-habit-4: #b07a7a;
  --color-habit-5: #7a9cc4;
  --radius-card: 16px;
  --radius-sm: 8px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #141414;
    --color-surface: #1e1e1e;
    --color-surface-pressed: #2a2a2a;
    --color-text: #ececec;
    --color-text-secondary: #999997;
    --color-text-tertiary: #666664;
    --color-border: rgba(255, 255, 255, 0.08);
  }
}

html {
  -webkit-tap-highlight-color: transparent;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family:
    'Inter',
    -apple-system,
    'Helvetica Neue',
    'Segoe UI',
    system-ui,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  line-height: 1.5;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes checkPop {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.15);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes shimmer {
  0% {
    opacity: 0.6;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0.6;
  }
}

.animate-fade-in {
  animation: fadeInUp 400ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.animate-check {
  animation: checkPop 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* Focus rings for accessibility */
*:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .animate-fade-in,
  .animate-check {
    animation: none;
  }
}

/* Tab bar safe area */
.safe-bottom {
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

import { useState, useMemo, useCallback, useEffect } from 'react'
import {
  getHabits,
  addHabit,
  updateHabit,
  removeHabit,
  getCheckinsToday,
  toggleCheckIn,
  getTodayMood,
  saveMood,
  getWeeklyData,
  getStreaks,
  readTheme,
  writeTheme,
  systemDark,
  getTodayString,
  formatDateGerman,
  type Habit,
  type MoodEntry,
  type DailyCounts,
} from './db'

// ── Constants ──

const HABIT_COLORS = [
  { name: 'Terrakotta', value: '#c4956a' },
  { name: 'Salbei', value: '#6a9c8a' },
  { name: 'Lavendel', value: '#8a7ab0' },
  { name: 'Ziegelrot', value: '#b07a7a' },
  { name: 'Türkis', value: '#7a9cc4' },
  { name: 'Senf', value: '#c4b06a' },
]

const MOODS = [
  { value: 1, label: 'Sehr schlecht', emoji: '😞' },
  { value: 2, label: 'Schlecht', emoji: '😕' },
  { value: 3, label: 'Ausgewogen', emoji: '😐' },
  { value: 4, label: 'Gut', emoji: '🙂' },
  { value: 5, label: 'Ausgezeichnet', emoji: '😊' },
] as const

const WEEKDAY_SHORT = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa']

// ── Today Screen ──

function TodayScreen() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [checked, setChecked] = useState<Set<string>>(new Set())
  const [streaks, setStreaks] = useState<Record<string, { current: number; longest: number }>>({})
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    ;(async () => {
      const h = await getHabits()
      const c = await getCheckinsToday()
      const s = await getStreaks()
      if (mounted) {
        setHabits(h)
        setChecked(c)
        setStreaks(s)
        setLoading(false)
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  const today = getTodayString()
  const completedCount = checked.size
  const totalCount = habits.length

  const handleToggle = useCallback(
    async (habitId: string) => {
      await toggleCheckIn(habitId)
      setChecked((prev) => {
        const next = new Set(prev)
        if (next.has(habitId)) next.delete(habitId)
        else next.add(habitId)
        return next
      })
    },
    [],
  )

  const progressPercent = totalCount > 0 ? (completedCount / totalCount) * 100 : 0

  const todayDate = new Date()
  const formatted = todayDate.toLocaleDateString('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  })

  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      {/* Header */}
      <div className="px-5 pt-14 pb-6">
        <p className="text-sm font-medium uppercase tracking-widest text-[var(--color-text-secondary)]">
          {formatted}
        </p>
        <h1 className="text-3xl font-bold tracking-tight mt-1">Heute</h1>
      </div>

      {/* Progress */}
      <div className="px-5 pb-5">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm text-[var(--color-text-secondary)]">
            {completedCount} von {totalCount} geschafft
          </span>
          <span className="text-sm font-semibold">{Math.round(progressPercent)}%</span>
        </div>
        <div className="h-2 bg-[var(--color-border)] rounded-full overflow-hidden">
          <div
            className="h-full bg-[var(--color-text)] rounded-full transition-all duration-500 ease-out"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>

      {/* Habit list */}
      <div className="px-5 flex-1 pb-24">
        {loading ? (
          <div className="space-y-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <div
                key={i}
                className="h-16 bg-[var(--color-border)] rounded-[var(--radius-card)] animate-shimmer"
              />
            ))}
          </div>
        ) : habits.length === 0 ? (
          <EmptyState
            title="Noch keine Habits"
            description="Gehe zu Einstellungen und füge deinen ersten Habit hinzu."
          />
        ) : (
          <div className="space-y-3">
            {habits.map((habit, index) => {
              const isDone = checked.has(habit.id)
              const streak = streaks[habit.id]
              return (
                <div
                  key={habit.id}
                  className="animate-fade-in"
                  style={{ animationDelay: `${index * 60}ms` }}
                >
                  <button
                    onClick={() => handleToggle(habit.id)}
                    className={`
                      w-full flex items-center gap-4 px-5 py-4
                      rounded-[var(--radius-card)]
                      transition-colors duration-200
                      ${isDone ? 'bg-[var(--color-surface-pressed)]' : 'bg-[var(--color-surface)]'}
                    `}
                    aria-label={`${habit.name}${isDone ? ' — abgehakt' : ' — abhaken'}`}
                  >
                    <div
                      className="w-7 h-7 rounded-full flex items-center justify-center text-sm font-bold text-white flex-shrink-0"
                      style={{ backgroundColor: habit.color }}
                    >
                      {habit.emoji}
                    </div>
                    <span className={`flex-1 text-base ${isDone ? 'text-[var(--color-text-secondary)] line-through' : ''}`}>
                      {habit.name}
                    </span>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      {streak.current > 0 && (
                        <span className="text-xs font-medium text-[var(--color-text-secondary)]">
                          {streak.current}×
                        </span>
                      )}
                      <div
                        className={`
                          w-7 h-7 rounded-full border-2 flex items-center justify-center
                          transition-all duration-200
                          ${isDone
                            ? 'border-[var(--color-text)] bg-[var(--color-text)]'
                            : 'border-[var(--color-border)]'
                          }
                        `}
                      >
                        {isDone && (
                          <svg
                            className="w-4 h-4 text-[var(--color-surface)] animate-check"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2.5"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          >
                            <path d="M5 13l4 4L19 7" />
                          </svg>
                        )}
                      </div>
                    </div>
                  </button>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

// ── Week Screen ──

function WeekScreen() {
  const [data, setData] = useState<DailyCounts[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    getWeeklyData().then((d) => {
      if (mounted) {
        setData(d)
        setLoading(false)
      }
    })
    return () => {
      mounted = false
    }
  }, [])

  if (loading) {
    return (
      <div className="flex flex-col flex-1 overflow-y-auto px-5 pt-14 pb-24">
        <p className="text-sm font-medium uppercase tracking-widest text-[var(--color-text-secondary)]">Diese Woche</p>
        <h2 className="text-2xl font-bold tracking-tight mt-1">Woche</h2>
        <div className="h-48 bg-[var(--color-border)] rounded-[var(--radius-card)] mt-6" />
      </div>
    )
  }

  if (data.length === 0 || data.every((d) => d.completed.length === 0 && !d.mood)) {
    return (
      <EmptyState title="Noch keine Daten" description="Lege Habits an und trage täglich deine Stimmung ein, damit hier Diagramme erscheinen." />
    )
  }

  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      <div className="px-5 pt-14 pb-6">
        <p className="text-sm font-medium uppercase tracking-widest text-[var(--color-text-secondary)]">
          Übersicht
        </p>
        <h2 className="text-3xl font-bold tracking-tight mt-1">Woche</h2>
      </div>

      <div className="px-5 flex-1 pb-24 space-y-6">
        {/* Completed count chart */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-sm font-semibold text-[var(--color-text-secondary)] uppercase tracking-wide mb-4">
            Erledigte Habits
          </h3>
          <div className="flex items-end gap-1.5 h-32">
            {data.map((d, i) => {
              const maxVal = Math.max(
                ...data.map((dd) => dd.completed.length),
                1,
              )
              const height = (d.completed.length / maxVal) * 100
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-1 h-full justify-end">
                  <span className="text-xs font-medium text-[var(--color-text-secondary)]">{d.completed.length}</span>
                  <div
                    className="w-full bg-[var(--color-text)] rounded-t-md transition-all duration-500"
                    style={{
                      height: `${Math.max(height, 8)}%`,
                      opacity: d.completed.length === 0 ? 0.15 : 0.8,
                    }}
                  />
                  <span className="text-[10px] text-[var(--color-text-tertiary)]">
                    {WEEKDAY_SHORT[new Date(d.date).getDay()]}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        {/* Mood chart */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-sm font-semibold text-[var(--color-text-secondary)] uppercase tracking-wide mb-4">
            Stimmung
          </h3>
          <div className="flex items-end gap-1.5 h-32">
            {data.map((d, i) => {
              const maxVal = Math.max(
                ...data.map((dd) => (dd.mood ? dd.mood.value : 0)),
                1,
              )
              const height = d.mood ? (d.mood.value / 5) * 100 : 0
              const moodEntry = d.mood
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-1 h-full justify-end">
                  {moodEntry ? (
                    <span className="text-xs">{MOODS[moodEntry.value - 1].emoji}</span>
                  ) : (
                    <span className="h-4" />
                  )}
                  <div
                    className={`w-full rounded-t-md transition-all duration-500 ${
                      moodEntry
                        ? moodEntry.value <= 2
                          ? 'bg-[#c4956a]'
                          : moodEntry.value === 3
                            ? 'bg-[#8a9a8a]'
                            : 'bg-[var(--color-text)]'
                        : ''
                    }`}
                    style={{
                      height: `${moodEntry ? Math.max(height, 8) : 8}%`,
                      opacity: moodEntry ? 0.8 : 0.1,
                    }}
                  />
                  <span className="text-[10px] text-[var(--color-text-tertiary)]">
                    {WEEKDAY_SHORT[new Date(d.date).getDay()]}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        {/* Raw dates */}
        <div className="space-y-1.5">
          {[...data].reverse().map((d) => (
            <div
              key={d.date}
              className="flex items-center justify-between text-sm py-2 border-b border-[var(--color-border)]"
            >
              <span className="text-[var(--color-text)]">{formatDateGerman(d.date)}</span>
              <span className="text-[var(--color-text-secondary)]">
                {d.completed.length}/{habitsCountPlaceholder()} Habits
                {d.mood ? ` · ${MOODS[d.mood.value - 1].emoji}` : ''}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// Placeholder — will be replaced once habits are accessible
function habitsCountPlaceholder(): number {
  return 0
}

// ── Mood entry ──

function MoodSection() {
  const [todayMood, setTodayMood] = useState<MoodEntry | null>(null)
  const [note, setNote] = useState('')
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    let mounted = true
    getTodayMood().then((m) => {
      if (mounted) {
        setTodayMood(m)
        if (m) setNote(m.note || '')
      }
    })
  }, [])

  const handleSave = async () => {
    setSaving(true)
    await saveMood(todayMood?.value || 3, note.trim() || undefined)
    const updated = await getTodayMood()
    if (updated) {
      setTodayMood(updated)
      setNote(updated.note || '')
    }
    setSaving(false)
  }

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-base font-semibold mb-3">Heutige Stimmung</h3>
        <div className="flex gap-2">
          {MOODS.map((m) => (
            <button
              key={m.value}
              onClick={async () => {
                await saveMood(m.value, note.trim() || undefined)
                setTodayMood(await getTodayMood())
              }}
              className={`
                flex-1 flex flex-col items-center gap-1.5 py-3 px-2
                rounded-[var(--radius-sm)] border transition-colors
                ${todayMood?.value === m.value
                  ? 'border-[var(--color-text)] bg-[var(--color-surface-pressed)]'
                  : 'border-[var(--color-border)] hover:border-[var(--color-text-secondary)]'
                }
              `}
              aria-label={m.label}
            >
              <span className="text-2xl">{m.emoji}</span>
              <span className="text-[10px] text-[var(--color-text-secondary)]">{m.label}</span>
            </button>
          ))}
        </div>
      </div>

      <div>
        <label htmlFor="mood-note" className="text-sm font-semibold block mb-2">
          Notiz (optional)
        </label>
        <textarea
          id="mood-note"
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Heute war…"
          rows={3}
          className="w-full bg-[var(--color-surface)] border border-[var(--color-border)] rounded-[var(--radius-sm)] px-4 py-3 text-base resize-none placeholder:text-[var(--color-text-tertiary)]"
        />
      </div>

      <button
        onClick={handleSave}
        disabled={saving}
        className="w-full py-3.5 bg-[var(--color-text)] text-[var(--color-surface)] text-sm font-semibold rounded-[var(--radius-sm)] transition-opacity disabled:opacity-50"
      >
        Speichern
      </button>
    </div>
  )
}

// ── Settings Screen ──

function SettingsScreen() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [streaks, setStreaks] = useState<Record<string, { current: number; longest: number }>>({})
  const [showNew, setShowNew] = useState(false)
  const [newName, setNewName] = useState('')
  const [newEmoji, setNewEmoji] = useState('💧')
  const [newColor, setNewColor] = useState(HABIT_COLORS[0].value)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editName, setEditName] = useState('')
  const [themeMode, setThemeMode] = useState<'light' | 'dark' | 'auto'>('auto')
  const [todayMood, setTodayMood] = useState<MoodEntry | null>(null)

  useEffect(() => {
    let mounted = true
    ;(async () => {
      const h = await getHabits()
      const s = await getStreaks()
      const m = await getTodayMood()
      if (mounted) {
        setHabits(h)
        setStreaks(s)
        setTodayMood(m)
        const stored = readTheme()
        setThemeMode(stored ? (stored === 'dark' ? 'dark' : 'light') : 'auto')
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  const handleAdd = async () => {
    if (!newName.trim()) return
    const id = await addHabit(newName.trim(), newEmoji, newColor)
    const updated = await getHabits()
    setHabits(updated)
    setNewName('')
    setShowNew(false)
  }

  const handleEdit = async (id: string) => {
    if (!editName.trim()) return
    await updateHabit(id, { name: editName.trim() })
    const updated = await getHabits()
    setHabits(updated)
    setEditingId(null)
    setEditName('')
  }

  const handleDelete = async (id: string) => {
    await removeHabit(id)
    setHabits(await getHabits())
  }

  const toggleTheme = async (mode: 'light' | 'dark' | 'auto') => {
    const newMode = mode === themeMode ? 'auto' : (mode as 'light' | 'dark')
    setThemeMode(newMode)
    if (newMode !== 'auto') {
      writeTheme(newMode)
    } else {
      try {
        localStorage.removeItem(readTheme ? '' : '')
      } catch {
        /* no-op */
      }
    }
  }

  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      <div className="px-5 pt-14 pb-6">
        <p className="text-sm font-medium uppercase tracking-widest text-[var(--color-text-secondary)]">
          Konfiguration
        </p>
        <h2 className="text-3xl font-bold tracking-tight mt-1">Einstellungen</h2>
      </div>

      <div className="px-5 flex-1 pb-24 space-y-6">
        {/* Theme toggle */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-base font-semibold mb-3">Erscheinungsbild</h3>
          <div className="flex gap-2">
            {(['auto', 'light', 'dark'] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => toggleTheme(mode)}
                className={`
                  flex-1 py-2.5 rounded-[var(--radius-sm)] text-xs font-medium border transition-colors
                  ${themeMode === mode
                    ? 'border-[var(--color-text)] bg-[var(--color-text)] text-[var(--color-surface)]'
                    : 'border-[var(--color-border)] text-[var(--color-text-secondary)]'
                  }
                `}
              >
                {mode === 'auto' ? 'System' : mode === 'light' ? 'Hell' : 'Dunkel'}
              </button>
            ))}
          </div>
        </div>

        {/* Mood today */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-base font-semibold mb-3">Heutige Stimmung</h3>
          {todayMood ? (
            <div className="flex items-center gap-3">
              <span className="text-3xl">{MOODS[todayMood.value - 1].emoji}</span>
              <div>
                <p className="font-medium">{MOODS[todayMood.value - 1].label}</p>
                {todayMood.note && (
                  <p className="text-sm text-[var(--color-text-secondary)] mt-0.5">{todayMood.note}</p>
                )}
              </div>
            </div>
          ) : (
            <MoodSection />
          )}
        </div>

        {/* Habits list */}
        <div>
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-base font-semibold">Habits</h3>
            <button
              onClick={() => setShowNew(!showNew)}
              className="text-sm font-medium text-[var(--color-text-secondary)] hover:text-[var(--color-text)]"
            >
              {showNew ? 'Abbrechen' : '+ Neu'}
            </button>
          </div>

          {showNew && (
            <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5 space-y-4 mb-3">
              <input
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                placeholder="Name des Habits"
                className="w-full bg-transparent border-b border-[var(--color-border)] pb-2 text-base placeholder:text-[var(--color-text-tertiary)] focus:border-[var(--color-text)] outline-none"
                autoFocus
                onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
              />
              <div>
                <label className="text-xs text-[var(--color-text-secondary)] block mb-2">Emoji</label>
                <div className="flex gap-2 flex-wrap">
                  {['💧', '🏃', '📚', '🧘', '✍️', '💪', '🎨', '🎵', '🍳', '💊'].map((em) => (
                    <button
                      key={em}
                      onClick={() => setNewEmoji(em)}
                      className={`w-9 h-9 rounded-full flex items-center justify-center text-lg transition-colors ${
                        newEmoji === em ? 'bg-[var(--color-surface-pressed)]' : ''
                      }`}
                    >
                      {em}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="text-xs text-[var(--color-text-secondary)] block mb-2">Farbe</label>
                <div className="flex gap-2">
                  {HABIT_COLORS.map((c) => (
                    <button
                      key={c.value}
                      onClick={() => setNewColor(c.value)}
                      className={`w-7 h-7 rounded-full transition-transform ${
                        newColor === c.value ? 'scale-125 ring-2 ring-[var(--color-text)] ring-offset-2' : ''
                      }`}
                      style={{ backgroundColor: c.value }}
                      aria-label={c.name}
                      title={c.name}
                    />
                  ))}
                </div>
              </div>
              <button
                onClick={handleAdd}
                disabled={!newName.trim()}
                className="w-full py-3 bg-[var(--color-text)] text-[var(--color-surface)] text-sm font-semibold rounded-[var(--radius-sm)] disabled:opacity-40"
              >
                Erstellen
              </button>
            </div>
          )}

          {habits.length === 0 && !showNew ? (
            <EmptyState title="Noch keine Habits" description="Tippe auf '+ Neu', um deinen ersten Gewohnheitstracker zu erstellen." />
          ) : (
            <div className="space-y-2">
              {habits.map((h) => (
                <div
                  key={h.id}
                  className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-4"
                >
                  {editingId === h.id ? (
                    <div className="flex gap-2 items-center">
                      <input
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleEdit(h.id)}
                        className="flex-1 bg-transparent border-b border-[var(--color-text)] pb-1 text-base outline-none"
                        autoFocus
                      />
                      <button
                        onClick={() => handleEdit(h.id)}
                        className="text-sm font-medium text-[var(--color-text)]"
                      >
                        OK
                      </button>
                      <button
                        onClick={() => setEditingId(null)}
                        className="text-sm text-[var(--color-text-secondary)]"
                      >
                        Abbr.
                      </button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-3">
                      <div
                        className="w-8 h-8 rounded-full flex items-center justify-center text-sm text-white"
                        style={{ backgroundColor: h.color }}
                      >
                        {h.emoji}
                      </div>
                      <span className="flex-1">{h.name}</span>
                      <div className="flex items-center gap-3">
                        {streaks[h.id]?.current > 0 && (
                          <span className="text-xs text-[var(--color-text-secondary)]">
                            {streaks[h.id].current}× heute / {streaks[h.id].longest}× lang
                          </span>
                        )}
                        <button
                          onClick={() => {
                            setEditingId(h.id)
                            setEditName(h.name)
                          }}
                          className="text-[var(--color-text-secondary)] hover:text-[var(--color-text)]"
                          aria-label={`${h.name} bearbeiten`}
                        >
                          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                            <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7" />
                            <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 8.5-8.5z" />
                          </svg>
                        </button>
                        <button
                          onClick={() => handleDelete(h.id)}
                          className="text-[#c4956a] hover:text-[#b07a7a]"
                          aria-label={`${h.name} löschen`}
                        >
                          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                            <path d="M3 6h18" />
                            <path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6" />
                            <path d="M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2" />
                          </svg>
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="pt-4 text-center text-xs text-[var(--color-text-tertiary)]">
          Rhythm v0.1.0 · Alle Daten lokal gespeichert
        </div>
      </div>
    </div>
  )
}

// ── Empty state ──

function EmptyState({ title, description }: { title: string; description: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="w-16 h-16 rounded-full bg-[var(--color-border)] flex items-center justify-center mb-4">
        <svg className="w-7 h-7 text-[var(--color-text-tertiary)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <circle cx="12" cy="12" r="9" />
          <path d="M12 8v4" />
          <path d="M12 16h.01" />
        </svg>
      </div>
      <p className="font-semibold text-lg">{title}</p>
      <p className="text-sm text-[var(--color-text-secondary)] mt-1.5 max-w-[240px]">{description}</p>
    </div>
  )
}

// ── App shell ──

type Tab = 'today' | 'week' | 'settings'

export default function App() {
  const [tab, setTab] = useState<Tab>('today')
  const [themeMode, setThemeMode] = useState<'light' | 'dark' | 'auto'>('auto')
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    const stored = readTheme()
    if (stored) {
      setThemeMode(stored)
    } else {
      setThemeMode(systemDark() ? 'dark' : 'light')
    }
    setMounted(true)
  }, [])

  useEffect(() => {
    if (!mounted) return
    const actual = themeMode === 'auto' ? (systemDark() ? 'dark' : 'light') : themeMode
    document.documentElement.classList.toggle('dark', actual === 'dark')
  }, [themeMode, mounted])

  const handleThemeOverride = (mode: 'light' | 'dark') => {
    writeTheme(mode)
    setThemeMode(mode)
  }

  return (
    <div className="h-dvh flex flex-col bg-[var(--color-bg)] text-[var(--color-text)]">
      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="flex-1 overflow-hidden">
          {tab === 'today' && <TodayScreen />}
          {tab === 'week' && <WeekScreen />}
          {tab === 'settings' && (
            <SettingsScreenWithTheme onThemeOverride={handleThemeOverride} themeMode={themeMode} />
          )}
        </div>
      </div>

      {/* Bottom tab bar */}
      <div className="safe-bottom border-t border-[var(--color-border)] bg-[var(--color-bg)]">
        <nav className="flex items-center justify-around py-2" role="navigation" aria-label="Hauptnavigation">
          <TabButton icon="check" label="Heute" active={tab === 'today'} onClick={() => setTab('today')} />
          <TabButton icon="chart" label="Woche" active={tab === 'week'} onClick={() => setTab('week')} />
          <TabButton icon="gear" label="Einstellungen" active={tab === 'settings'} onClick={() => setTab('settings')} />
        </nav>
      </div>
    </div>
  )
}

// ── Tab button ──

function TabButton({
  icon,
  label,
  active,
  onClick,
}: {
  icon: string
  label: string
  active: boolean
  onClick: () => void
}) {
