    <button
      onClick={onClick}
      className="flex flex-col items-center gap-0.5 py-1 px-5 min-h-[44px] justify-center"
      aria-label={label}
      aria-current={active ? 'page' : undefined}
    >
      {icon === 'check' && (
        <svg className={`w-5 h-5 ${active ? 'opacity-100' : 'opacity-40'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M9 11l3 3L22 4" />
          <path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11" />
        </svg>
      )}
      {icon === 'chart' && (
        <svg className={`w-5 h-5 ${active ? 'opacity-100' : 'opacity-40'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
          <path d="M3 3v18h18" />
          <path d="M18 17V9" />
          <path d="M13 17V5" />
          <path d="M8 17v-3" />
        </svg>
      )}
      {icon === 'gear' && (
        <svg className={`w-5 h-5 ${active ? 'opacity-100' : 'opacity-40'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
          <circle cx="12" cy="12" r="3" />
          <path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-4 0v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 010-4h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 012.83-2.83l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 014 0v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 010 4h-.09a1.65 1.65 0 00-1.51 1z" />
        </svg>
      )}
      <span className={`text-[11px] font-medium ${active ? 'opacity-100' : 'opacity-50'}`}>{label}</span>
    </button>
  )
}

// ── Settings with theme override ──

function SettingsScreenWithTheme({
  onThemeOverride,
  themeMode,
}: {
  onThemeOverride: (mode: 'light' | 'dark') => void
  themeMode: string
}) {
  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      <div className="px-5 pt-14 pb-6">
        <p className="text-sm font-medium uppercase tracking-widest text-[var(--color-text-secondary)]">
          Konfiguration
        </p>
        <h2 className="text-3xl font-bold tracking-tight mt-1">Einstellungen</h2>
      </div>

      <div className="px-5 flex-1 pb-24 space-y-6">
        {/* Theme */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-base font-semibold mb-3">Erscheinungsbild</h3>
          <div className="flex gap-2">
            <button
              onClick={() => onThemeOverride('light')}
              className={`flex-1 py-2.5 rounded-[var(--radius-sm)] text-xs font-medium border transition-colors ${
                themeMode === 'light' ? 'border-[var(--color-text)] bg-[var(--color-text)] text-[var(--color-surface)]' : 'border-[var(--color-border)] text-[var(--color-text-secondary)]'
              }`}
