            <button
              onClick={() => onThemeOverride('dark')}
              className={`flex-1 py-2.5 rounded-[var(--radius-sm)] text-xs font-medium border transition-colors ${
                themeMode === 'dark' ? 'border-[var(--color-text)] bg-[var(--color-text)] text-[var(--color-surface)]' : 'border-[var(--color-border)] text-[var(--color-text-secondary)]'
              }`}
            >
              Dunkel
            </button>
          </div>
          <p className="text-[11px] text-[var(--color-text-tertiary)] mt-2">
            Standardmäßig folgt Rhythm deinem System-Setting.
          </p>
        </div>

        {/* Today's mood */}
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5">
          <h3 className="text-base font-semibold mb-3">Heutige Stimmung</h3>
          <TodayMoodInline />
        </div>

        {/* Habits list */}
        <HabitsManagement />

        <div className="pt-4 text-center text-xs text-[var(--color-text-tertiary)]">
          Rhythm v0.1.0 · Alle Daten lokal gespeichert
        </div>
      </div>
    </div>
  )
}

// ── Inline today mood ──

function TodayMoodInline() {
  const [mood, setMood] = useState<MoodEntry | null>(null)
  const [note, setNote] = useState('')
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    getTodayMood().then((m) => {
      if (mounted) {
        setMood(m)
        if (m) setNote(m.note || '')
        setLoading(false)
      }
    })
    return () => {
      mounted = false
    }
  }, [])

  const handlePick = async (value: number) => {
    await saveMood(value, note.trim() || undefined)
    const updated = await getTodayMood()
    if (updated) setMood(updated)
  }

  const handleSaveNote = async () => {
    if (!mood) return
    await saveMood(mood.value, note.trim() || undefined)
    const updated = await getTodayMood()
    if (updated) setMood(updated)
  }

  if (loading) {
    return <div className="h-20 bg-[var(--color-border)] rounded-[var(--radius-sm)]" />
  }

  if (mood) {
    return (
      <div className="flex items-center gap-4">
        <span className="text-4xl">{MOODS[mood.value - 1].emoji}</span>
        <div className="flex-1">
          <p className="font-medium">{MOODS[mood.value - 1].label}</p>
          {mood.note && <p className="text-sm text-[var(--color-text-secondary)] mt-0.5">{mood.note}</p>}
        </div>
        <button
          onClick={() => setMood(null)}
          className="text-xs text-[var(--color-text-secondary)]"
        >
          Ändern
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        {MOODS.map((m) => (
          <button
            key={m.value}
            onClick={() => handlePick(m.value)}
            className="flex-1 flex flex-col items-center gap-1 py-3 px-2 rounded-[var(--radius-sm)] border border-[var(--color-border)] hover:border-[var(--color-text-secondary)] transition-colors"
          >
            <span className="text-2xl">{m.emoji}</span>
            <span className="text-[10px] text-[var(--color-text-secondary)]">{m.label}</span>
          </button>
        ))}
      </div>
      <textarea
        value={note}
        onChange={(e) => setNote(e.target.value)}
        placeholder="Notiz (optional)"
        rows={2}
        className="w-full bg-transparent border-b border-[var(--color-border)] pb-2 text-sm resize-none placeholder:text-[var(--color-text-tertiary)]"
      />
      <button
        onClick={handleSaveNote}
        className="w-full py-3 bg-[var(--color-text)] text-[var(--color-surface)] text-sm font-semibold rounded-[var(--radius-sm)]"
      >
        Speichern
      </button>
    </div>
  )
}

// ── Habits management (for settings screen) ──

function HabitsManagement() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [streaks, setStreaks] = useState<Record<string, { current: number; longest: number }>>({})
  const [showNew, setShowNew] = useState(false)
  const [newName, setNewName] = useState('')
  const [newEmoji, setNewEmoji] = useState('💧')
  const [newColor, setNewColor] = useState(HABIT_COLORS[0].value)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editName, setEditName] = useState('')

  useEffect(() => {
    let mounted = true
    ;(async () => {
      const h = await getHabits()
      const s = await getStreaks()
      if (mounted) {
        setHabits(h)
        setStreaks(s)
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  const handleAdd = async () => {
    if (!newName.trim()) return
    await addHabit(newName.trim(), newEmoji, newColor)
    const updated = await getHabits()
    const s = await getStreaks()
    setHabits(updated)
    setStreaks(s)
    setNewName('')
    setShowNew(false)
  }

  const handleEdit = async (id: string) => {
    if (!editName.trim()) return
    await updateHabit(id, { name: editName.trim() })
    const updated = await getHabits()
    const s = await getStreaks()
    setHabits(updated)
    setStreaks(s)
    setEditingId(null)
    setEditName('')
  }

  const handleDelete = async (id: string) => {
    await removeHabit(id)
    const updated = await getHabits()
    const s = await getStreaks()
    setHabits(updated)
    setStreaks(s)
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-base font-semibold">Habits</h3>
        <button
          onClick={() => setShowNew(!showNew)}
          className="text-sm font-medium text-[var(--color-text-secondary)] hover:text-[var(--color-text)]"
        >
          {showNew ? 'Abbrechen' : '+ Neu'}
        </button>
      </div>

      {showNew && (
        <div className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-5 space-y-4 mb-3">
          <input
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            placeholder="Name des Habits"
            className="w-full bg-transparent border-b border-[var(--color-border)] pb-2 text-base placeholder:text-[var(--color-text-tertiary)] focus:border-[var(--color-text)] outline-none"
            autoFocus
            onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
          />
          <div>
            <label className="text-xs text-[var(--color-text-secondary)] block mb-2">Emoji</label>
            <div className="flex gap-2 flex-wrap">
              {['💧', '🏃', '📚', '🧘', '✍️', '💪', '🎨', '🎵', '🍳', '💊'].map((em) => (
                <button
                  key={em}
                  onClick={() => setNewEmoji(em)}
                  className={`w-9 h-9 rounded-full flex items-center justify-center text-lg transition-transform ${
                    newEmoji === em ? 'bg-[var(--color-surface-pressed)]' : ''
                  }`}
                >
                  {em}
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="text-xs text-[var(--color-text-secondary)] block mb-2">Farbe</label>
            <div className="flex gap-2">
              {HABIT_COLORS.map((c) => (
                <button
                  key={c.value}
                  onClick={() => setNewColor(c.value)}
                  className={`w-7 h-7 rounded-full transition-transform ${
                    newColor === c.value ? 'scale-125 ring-2 ring-[var(--color-text)] ring-offset-2' : ''
                  }`}
                  style={{ backgroundColor: c.value }}
                  aria-label={c.name}
                  title={c.name}
                />
              ))}
            </div>
          </div>
          <button
            onClick={handleAdd}
            disabled={!newName.trim()}
            className="w-full py-3 bg-[var(--color-text)] text-[var(--color-surface)] text-sm font-semibold rounded-[var(--radius-sm)] disabled:opacity-40"
          >
            Erstellen
          </button>
        </div>
      )}

      {habits.length === 0 && !showNew ? (
        <EmptyState title="Noch keine Habits" description="Tippe auf '+ Neu', um deinen ersten Gewohnheitstracker zu erstellen." />
      ) : (
        <div className="space-y-2">
          {habits.map((h) => (
            <div key={h.id} className="bg-[var(--color-surface)] rounded-[var(--radius-card)] p-4">
              {editingId === h.id ? (
                <div className="flex gap-2 items-center">
                  <input
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleEdit(h.id)}
                    className="flex-1 bg-transparent border-b border-[var(--color-text)] pb-1 text-base outline-none"
                    autoFocus
                  />
                  <button onClick={() => handleEdit(h.id)} className="text-sm font-medium text-[var(--color-text)]">
                    OK
                  </button>
                  <button onClick={() => setEditingId(null)} className="text-sm text-[var(--color-text-secondary)]">
                    Abbr.
                  </button>
                </div>
              ) : (
                <div className="flex items-center gap-3">
                  <div
                    className="w-8 h-8 rounded-full flex items-center justify-center text-sm text-white"
                    style={{ backgroundColor: h.color }}
                  >
                    {h.emoji}
                  </div>
                  <span className="flex-1">{h.name}</span>
                  <div className="flex items-center gap-3">
                    {streaks[h.id]?.current > 0 && (
                      <span className="text-xs text-[var(--color-text-secondary)]">
                        {streaks[h.id].current}× / {streaks[h.id].longest}×
                      </span>
                    )}
                    <button
                      onClick={() => {
                        setEditingId(h.id)
                        setEditName(h.name)
                      }}
                      className="text-[var(--color-text-secondary)] hover:text-[var(--color-text)]"
                      aria-label={`${h.name} bearbeiten`}
                    >
                      <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                        <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7" />
                        <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 8.5-8.5z" />
                      </svg>
                    </button>
                    <button
                      onClick={() => handleDelete(h.id)}
                      className="text-[#c4956a] hover:text-[#b07a7a]"
                      aria-label={`${h.name} löschen`}
                    >
                      <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                        <path d="M3 6h18" />
                        <path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6" />
                        <path d="M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2" />
                      </svg>
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

