    setStreaks(await getStreaks())
    setEditingId(null)
    setEditName('')
  }

  const handleDelete = async (id: string) => {
    await removeHabit(id)
    setHabits(await getHabits())
    setStreaks(await getStreaks())
  }

  const handlePickMood = async (value: number) => {
    await saveMood(value, moodNote || undefined)
    setTodayMood(await getTodayMood())
    setPickValue(value)
  }

  const handleSaveNote = async () => {
    if (!todayMood) return
    await saveMood(todayMood.value, moodNote.trim() || undefined)
    setTodayMood(await getTodayMood())
  }

