# Create minimal PNG placeholders using base64 - 192x192 solid dark
echo -n 'iVBORw0KGgoAAAANSUhEUgAAARAAAAACACAQAAAACvuf3kAAAAIGNIUk0AAHomAACHw...
' | head -c 0 > /dev/null

# Actually let's just create them using node
node -e '
const fs = require("fs");
const { createWriteStream } = fs;

function createSolidPNG(size, r, g, b) {
  // Minimal PNG: IHDR + IDAT (solid color)
  const chunk = (type, data) => {
    const c = Buffer.concat([Buffer.from(type), data]);
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length, 0);
    return Buffer.concat([len, c, Buffer.alloc(4)]);
  };
  const crc = (data) => {
    // Simple CRC32 for PNG
    let c = 0xffffffff;
    for (let i = 0; i < data.length; i++) {
      c ^= data[i];
      for (let j = 0; j < 8; j++) {
        c = (c >>> 1) ^ (c & 1 ? 0xedb88320 : 0);
      }
    }
    return Buffer.from([((c >>> 24) & 0xff), ((c >>> 16) & 0xff), ((c >>> 8) & 0xff), (c & 0xff)]);
  };

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr.writeUInt8(8, 8); // bit depth
  ihdr.writeUInt8(2, 9); // color type (RGB)
  ihdr.writeUInt8(0, 10); // compression
  ihdr.writeUInt8(0, 11); // filter
  ihdr.writeUInt8(0, 12); // interlace

  const row = Buffer.alloc(size * 3);
  for (let i = 0; i < row.length; i++) {
    row[i] = [r, g, b][(i % 3)];
  }

  const filterZero = Buffer.alloc(1 + size * 3);
  for (let i = 0; i < size * 3; i++) filterZero[i + 1] = row[i];

  const zlib = require("zlib");
  const compressed = zlib.deflateSync(filterZero);

  const png = Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", compressed),
    chunk("IEND", Buffer.alloc(0))
  ]);
  return png;
}

const dark = createSolidPNG(512, 26, 26, 26);
const light = createSolidPNG(512, 250, 249, 247);
const p192 = createSolidPNG(192, 26, 26, 26);

fs.writeFileSync("/Users/cedi/Clouds/Projekte/KI/LLM-Bench/tests/habit-tracker/Qwen3.6-35B-A3B-4bit/public/pwa-512x512.png", dark);
fs.writeFileSync("/Users/cedi/Clouds/Projekte/KI/LLM-Bench/tests/habit-tracker/Qwen3.6-35B-A3B-4bit/public/pwa-192x192.png", p192);
fs.writeFileSync("/Users/cedi/Clouds/Projekte/KI/LLM-Bench/tests/habit-tracker/Qwen3.6-35B-A3B-4bit/public/apple-touch-icon.png", light);
console.log("PNGs created");
'

