import { useState, useEffect, useCallback } from 'react'
import {
  getHabits,
  getCheckinsToday,
  toggleCheckIn,
  getStreaks,
  getTodayString,
  type Habit,
} from '../db'

export default function TodayScreen() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [checked, setChecked] = useState<Set<string>>(new Set())
  const [streaks, setStreaks] = useState<Record<string, { current: number; longest: number }>>({})
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    ;(async () => {
      const h = await getHabits()
      const c = await getCheckinsToday()
      const s = await getStreaks()
      if (mounted) {
        setHabits(h)
        setChecked(c)
        setStreaks(s)
        setLoading(false)
      }
    })()
    return () => { mounted = false }
  }, [])

  const completedCount = checked.size
  const totalCount = habits.length
  const progressPercent = totalCount > 0 ? (completedCount / totalCount) * 100 : 0

  const todayDate = new Date()
  const formatted = todayDate.toLocaleDateString('de-DE', {
    weekday: 'long', day: 'numeric', month: 'long'
  })

  const handleToggle = useCallback(async (habitId: string) => {
    await toggleCheckIn(habitId)
    setChecked(prev => {
      const next = new Set(prev)
      next.has(habitId) ? next.delete(habitId) : next.add(habitId)
      return next
    })
  }, [])

  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      {/* Header */}
      <div className="px-5 pt-14 pb-5">
        <p className="text-xs font-semibold uppercase tracking-widest text-[var(--color-text-secondary)]">
          {formatted}
        </p>
        <h1 className="text-3xl font-bold tracking-tight mt-1 text-[var(--color-text)]">Heute</h1>
      </div>

      {/* Progress */}
      <div className="px-5 pb-5">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs text-[var(--color-text-secondary)]">
            {completedCount} von {totalCount} geschafft
          </span>
          <span className="text-xs font-semibold">{Math.round(progressPercent)}%</span>
        </div>
        <div className="h-1.5 bg-[var(--color-border)] rounded-full overflow-hidden">
          <div
            className="h-full bg-[var(--color-text)] rounded-full transition-all duration-500 ease-out"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>

      {/* Habit list */}
      <div className="px-5 flex-1 pb-24">
        {loading ? (
          <div className="space-y-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="h-14 bg-[var(--color-border)] rounded-xl animate-pulse" />
            ))}
          </div>
        ) : habits.length === 0 ? (
          <EmptyState title="Noch keine Habits" description="Gehe zu Einstellungen und füge deinen ersten Habit hinzu." />
        ) : (
          <div className="space-y-2.5">
            {habits.map((habit, index) => {
              const isDone = checked.has(habit.id)
              const streak = streaks[habit.id]
              return (
                <div
                  key={habit.id}
                  className="animate-[fadeIn_0.4s_ease-out_both]"
                  style={{ animationDelay: `${index * 60}ms` }}
                >
                  <button
                    onClick={() => handleToggle(habit.id)}
                    className={`
                      w-full flex items-center gap-3.5 px-4 py-3.5
                      rounded-xl transition-colors duration-200
                      ${isDone ? 'bg-[var(--color-surface-pressed)]' : 'bg-[var(--color-surface)]'}
                    `}
                    aria-label={`${habit.name}${isDone ? ' — abgehakt' : ' — abhaken'}`}
                  >
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center text-base text-white flex-shrink-0"
                      style={{ backgroundColor: habit.color }}
                    >
                      {habit.emoji}
                    </div>
                    <span className={`flex-1 text-sm ${isDone ? 'text-[var(--color-text-secondary)] line-through' : 'text-[var(--color-text)]'}`}>
                      {habit.name}
                    </span>
                    <div className="flex items-center gap-2.5 flex-shrink-0">
                      {streak && streak.current > 0 && (
                        <span className="text-[10px] font-medium text-[var(--color-text-secondary)]">
                          {streak.current}×
                        </span>
                      )}
                      <div
                        className={`
                          w-7 h-7 rounded-full border-2 flex items-center justify-center
                          transition-all duration-200
                          ${isDone ? 'border-[var(--color-text)] bg-[var(--color-text)]' : 'border-[var(--color-border)]'}
                        `}
                      >
                        {isDone && (
                          <svg className="w-3.5 h-3.5 text-[var(--color-surface)] animate-[checkPop_0.2s_ease-out]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M5 13l4 4L19 7" />
                          </svg>
                        )}
                      </div>
                    </div>
                  </button>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

function EmptyState({ title, description }: { title: string; description: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-14 text-center">
      <div className="w-14 h-14 rounded-full bg-[var(--color-border)] flex items-center justify-center mb-3">
        <svg className="w-6 h-6 text-[var(--color-text-tertiary)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <circle cx="12" cy="12" r="9" />
          <path d="M12 8v4" />
          <path d="M12 16h.01" />
        </svg>
      </div>
      <p className="font-semibold text-base">{title}</p>
      <p className="text-xs text-[var(--color-text-secondary)] mt-1 max-w-[220px]">{description}</p>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { getWeeklyData, getHabits, formatDateGerman, type DailyCounts, type Habit } from '../db'

const WEEKDAY_SHORT = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa']
const MOOD_EMOJIS = ['', '😞', '😕', '😐', '🙂', '😊']

export default function WeekScreen() {
  const [data, setData] = useState<DailyCounts[]>([])
  const [habits, setHabits] = useState<Habit[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    Promise.all([getWeeklyData(), getHabits()]).then(([d, h]) => {
      if (mounted) { setData(d); setHabits(h); setLoading(false) }
    })
    return () => { mounted = false }
  }, [])

  if (loading) {
    return (
      <div className="flex flex-col flex-1 overflow-y-auto px-5 pt-14 pb-24">
        <p className="text-xs font-semibold uppercase tracking-widest text-[var(--color-text-secondary)]">Übersicht</p>
        <h2 className="text-2xl font-bold tracking-tight mt-1 text-[var(--color-text)]">Woche</h2>
        <div className="h-48 bg-[var(--color-border)] rounded-xl mt-5 animate-pulse" />
      </div>
    )
  }

  const hasAnyData = data.some(d => d.completed.length > 0 || d.mood)
  if (!hasAnyData) {
    return (
      <EmptyState title="Noch keine Daten" description="Lege Habits an und trage täglich deine Stimmung ein." />
    )
  }

  const maxHabits = habits.length || 1
  const maxMood = 5

  return (
    <div className="flex flex-col flex-1 overflow-y-auto">
      <div className="px-5 pt-14 pb-5">
        <p className="text-xs font-semibold uppercase tracking-widest text-[var(--color-text-secondary)]">
          {formatDateGerman(data[6].date)} — {formatDateGerman(data[0].date)}
        </p>
        <h2 className="text-3xl font-bold tracking-tight mt-1 text-[var(--color-text)]">Woche</h2>
      </div>

      <div className="px-5 flex-1 pb-24 space-y-5">
        {/* Completed chart */}
        <div className="bg-[var(--color-surface)] rounded-xl p-4">
          <h3 className="text-[10px] font-semibold text-[var(--color-text-secondary)] uppercase tracking-widest mb-3">
            Erledigte Habits
          </h3>
          <div className="flex items-end gap-1.5 h-28">
            {data.map((d, i) => {
              const height = (d.completed.length / maxHabits) * 100
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-1 h-full justify-end">
                  {d.completed.length > 0 && (
                    <span className="text-[10px] font-medium text-[var(--color-text-secondary)]">{d.completed.length}</span>
                  )}
                  <div
                    className="w-full bg-[var(--color-text)] rounded-t-md transition-all duration-500"
                    style={{ height: `${Math.max(height, 6)}%`, opacity: d.completed.length === 0 ? 0.15 : 0.75 }}
                  />
                  <span className="text-[9px] text-[var(--color-text-tertiary)]">
                    {WEEKDAY_SHORT[new Date(d.date).getDay()]}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        {/* Mood chart */}
        <div className="bg-[var(--color-surface)] rounded-xl p-4">
          <h3 className="text-[10px] font-semibold text-[var(--color-text-secondary)] uppercase tracking-widest mb-3">
            Stimmung
          </h3>
          <div className="flex items-end gap-1.5 h-28">
            {data.map((d, i) => {
              const moodH = d.mood ? (d.mood.value / maxMood) * 100 : 0
              const moodEntry = d.mood
              const baseColor = moodEntry
                ? moodEntry.value <= 2
                  ? '#c4956a'
                  : moodEntry.value === 3
                    ? '#8a9a8a'
                    : '#7a9cc4'
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-1 h-full justify-end">
                  {moodEntry ? (
                    <span className="text-base">{MOOD_EMOJIS[moodEntry.value]}</span>
                  ) : (
                    <span className="h-4" />
                  )}
                  <div
                    className={`w-full rounded-t-md transition-all duration-500`}
                    style={{
                      height: `${moodEntry ? Math.max(moodH, 6) : 6}%`,
                      backgroundColor: moodEntry ? baseColor : 'var(--color-border)',
                      opacity: moodEntry ? 0.75 : 0.1,
                    }}
                  />
                  <span className="text-[9px] text-[var(--color-text-tertiary)]">
                    {WEEKDAY_SHORT[new Date(d.date).getDay()]}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        {/* Day details */}
        <div className="space-y-1.5">
          {[...data].reverse().map(d => (
            <div key={d.date} className="flex items-center justify-between text-xs py-1.5 border-b border-[var(--color-border)]">
              <span className="text-[var(--color-text)] font-medium">
                {formatDateGerman(d.date)}
              </span>
              <span className="text-[var(--color-text-secondary)]">
                {d.completed.length}/{maxHabits} Habits
                {d.mood ? ` · ${MOOD_EMOJIS[d.mood.value]}` : ' · keine Stimmung'}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

function EmptyState({ title, description }: { title: string; description: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-14 text-center">
      <div className="w-14 h-14 rounded-full bg-[var(--color-border)] flex items-center justify-center mb-3">
        <svg className="w-6 h-6 text-[var(--color-text-tertiary)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <rect x="3" y="3" width="18" height="18" rx="2" />
          <path d="M3 15l4-4 3 3 4-5 7 7" />
        </svg>
      </div>
      <p className="font-semibold text-base">{title}</p>
      <p className="text-xs text-[var(--color-text-secondary)] mt-1 max-w-[220px]">{description}</p>
    </div>
  )
}

